          destRight[di + 1] += srcRight[i + 1] * gR;
          destLeft[di + 2] += srcLeft[i + 2] * gL;
          destRight[di + 2] += srcRight[i + 2] * gR;
          destLeft[di + 3] += srcLeft[i + 3] * gL;
